      SUBROUTINE FILL23      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM23.CIN'C      KOUNTO = 0C    5 NUM = 0      KOUNT = 0C   10 NUM = NUM + 1      I = ISTOR(NUM)      TYPE = IDATA(I)C      IF (TYPE .EQ. 23) GO TO 230      GO TO 500C  230 K1REG = IDATA(I+1)      K2REG = IDATA(I+2)      IOPN = IDATA(I+3)      JREG = IDATA(I+4)      K1TIE = TIE(I+1)      K2TIE = TIE(I+2)      JTIE = TIE(I+4)      CALL DEPEND      IF (JTIE .EQ. 100) THEN        IVA = 0        DO 235 J = 1, NPVAR        IF (DATA(J + JREG) .GT. 0.5) IVA = 1  235   CONTINUE        IF (IVA .GT. 0) KOUNT = KOUNT + 1      ENDIF      GO TO 500C  500 IF (NUM .LE. NEL) GO TO 10      IF (KOUNT .GT. KOUNTO) THEN        KOUNTO = KOUNT        GO TO 5      ENDIFC      RETURN      END